BEGIN;
CREATE TEMP TABLE push_results(name text);
CREATE FUNCTION pg_temp.push_check(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS NOT TRUE THEN RAISE EXCEPTION 'Push test failed: %',label; END IF; INSERT INTO push_results VALUES(label); END $$;
DO $test$
DECLARE
 company uuid:='11111111-1111-1111-1111-111111111111'; driver_user uuid:='cccccccc-cccc-cccc-cccc-cccccccccccc';
 other_company uuid:='22222222-2222-2222-2222-222222222222';other_user uuid:='ffffffff-ffff-ffff-ffff-ffffffffffff';
 driver uuid:='c1000000-0000-0000-0000-000000000001';device uuid:=gen_random_uuid();device2 uuid:=gen_random_uuid();route uuid;result jsonb;address uuid;job record;job2 record;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',driver_user::text,true);
 result:=public.registrar_dispositivo_push(device,company,'test-registration-token-one');
 PERFORM pg_temp.push_check(result->>'sucesso'='true','approved driver registers own device');
 result:=public.registrar_dispositivo_push(device,other_company,'test-registration-token-one');
 PERFORM pg_temp.push_check(result->>'sucesso'='false','foreign company cannot receive own tokens');
 PERFORM set_config('request.jwt.claim.sub',other_user::text,true);
 result:=public.registrar_dispositivo_push(device,other_company,'another-registration-token');
 PERFORM pg_temp.push_check(result->>'sucesso'='false','another driver cannot overwrite a device ID');
 PERFORM set_config('request.jwt.claim.sub',driver_user::text,true);
 result:=public.registrar_dispositivo_push(device2,company,'test-registration-token-two');
 PERFORM pg_temp.push_check(result->>'sucesso'='true','second device registered separately');
 PERFORM pg_temp.push_check(NOT has_table_privilege('authenticated','public.push_dispositivos','SELECT') AND NOT has_table_privilege('authenticated','public.push_envios','SELECT') AND NOT has_function_privilege('authenticated','public.reivindicar_push_envios(int)','EXECUTE'),'client cannot read tokens or claim server jobs');
 INSERT INTO public.clientes_enderecos(empresa_id,nome_identificador,endereco_completo,numero,bairro,cidade,cep,latitude,longitude) VALUES(company,'Push test','Rua teste','1','Centro','Teste','00000-000',-27.5,-48.5) RETURNING id INTO address;
 INSERT INTO public.rotas_planejadas(empresa_id,motorista_id,idempotency_key,status,distancia_original_km,tempo_original_minutos,distancia_otimizada_km,tempo_otimizado_minutos,percentual_economia_km,percentual_economia_tempo,ordem_paradas_json) VALUES(company,driver,'PUSH-TEST','planejada',5,10,5,10,0,0,'[]') RETURNING id INTO route;
 INSERT INTO public.entregas(empresa_id,rota_id,motorista_id,cliente_endereco_id,codigo_rastreio,destinatario_nome,status,tipo_tarefa) VALUES(company,route,driver,address,'PUSH-TASK','Pessoa','atribuida','entrega');
 INSERT INTO public.operacoes_envio_motorista(empresa_id,chave,payload_hash,resultado) VALUES(company,'PUSH-EVENT','hash',jsonb_build_object('sucesso',true,'nova_rota_id',route,'coletas_adicionadas',0));
 PERFORM pg_temp.push_check((SELECT count(*)=2 AND bool_and(tipo='nova_rota' AND quantidade=1) FROM public.push_envios WHERE rota_id=route),'one notification per opted-in device after committed dispatch');
 INSERT INTO public.operacoes_envio_motorista(empresa_id,chave,payload_hash,resultado) VALUES(company,'PUSH-EVENT','hash','{}') ON CONFLICT DO NOTHING;
 PERFORM pg_temp.push_check((SELECT count(*)=2 FROM public.push_envios WHERE rota_id=route),'idempotent dispatch does not enqueue duplicates');
 SELECT * INTO job FROM public.reivindicar_push_envios(1);
 SELECT * INTO job2 FROM public.reivindicar_push_envios(1);
 PERFORM pg_temp.push_check(job.id<>job2.id AND job.claim_token<>job2.claim_token,'claimed jobs have separate leases');
 PERFORM pg_temp.push_check(NOT public.finalizar_push_envio(job.id,gen_random_uuid(),'aceito'),'stale worker cannot acknowledge another lease');
 PERFORM public.finalizar_push_envio(job.id,job.claim_token,'aceito');
 PERFORM pg_temp.push_check((SELECT status='aceito_fcm' FROM public.push_envios WHERE id=job.id),'FCM acceptance recorded without claiming phone delivery');
 PERFORM public.finalizar_push_envio(job2.id,job2.claim_token,'repetir','HTTP_503');
 PERFORM pg_temp.push_check((SELECT status='pendente' AND proxima_tentativa>now() FROM public.push_envios WHERE id=job2.id),'transient failure is retried after backoff');
 UPDATE public.push_envios SET proxima_tentativa=now() WHERE id=job2.id;
 SELECT * INTO job2 FROM public.reivindicar_push_envios(1);
 PERFORM public.finalizar_push_envio(job2.id,job2.claim_token,'invalido','UNREGISTERED');
 PERFORM pg_temp.push_check((SELECT count(*)=1 FROM public.push_dispositivos WHERE ativo),'unregistered device disabled without disabling other device');
 INSERT INTO public.operacoes_envio_motorista(empresa_id,chave,payload_hash,resultado) VALUES(company,'PUSH-COLLECTION','hash',jsonb_build_object('sucesso',true,'rota_ativa_id',route,'coletas_adicionadas',2));
 PERFORM pg_temp.push_check((SELECT count(*)=1 AND bool_and(tipo='nova_coleta' AND quantidade=2) FROM public.push_envios WHERE evento LIKE 'PUSH-COLLECTION:%'),'collection event only targets active devices');
 UPDATE public.rotas_planejadas SET status='cancelada' WHERE id=route;
 PERFORM public.reivindicar_push_envios(10);
 PERFORM pg_temp.push_check((SELECT bool_and(status='cancelado') FROM public.push_envios WHERE evento LIKE 'PUSH-COLLECTION:%'),'obsolete route is cancelled before offline delivery');
 result:=public.desativar_dispositivo_push(device);
 PERFORM pg_temp.push_check(result->>'sucesso'='true' AND NOT EXISTS(SELECT 1 FROM public.push_dispositivos WHERE id=device AND ativo),'driver can opt out');
END $test$;
SELECT count(*)::int AS push_passed FROM push_results;
ROLLBACK;
